mapper.select:
select b.handle sponsorHandle, r.sponsor_brand_id sponsorBrandId, r.sponsor_message sponsorMessage, b.brand_name sponsorName, b.customer_id sponsorUserId, b.avator sponsorAvatar, r.amount amount, r.created_at createdAt from user_sponsorship_record r inner join brand b on r.sponsor_brand_id = b.id where r.sponsoree_brand_id = #{currentBrandId}
and locate(#{dto.q}, b.brand_name) > 0
order by r.created_at desc
